import{_ as i,c as a,o as r,ak as t}from"./chunks/framework.gmyagHYt.js";const u=JSON.parse('{"title":"服务条款","description":"","frontmatter":{"title":"服务条款","sidebar":false},"headers":[],"relativePath":"terms/index.md","filePath":"terms/index.md"}'),l={name:"terms/index.md"};function s(o,e,n,c,p,h){return r(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="服务条款" tabindex="-1">服务条款 <a class="header-anchor" href="#服务条款" aria-label="Permalink to “服务条款”">​</a></h1><p><strong>最后更新日期：2026 年 9 月 10 日</strong></p><p>欢迎使用 ETS2LA-CN 提供的 Discord App 及相关消息同步服务。</p><p>本服务条款（以下简称“本条款”）适用于您使用 ETS2LA-CN Discord App（以下简称“本应用”）及相关消息同步服务的行为。</p><p>本应用主要用于将指定 Discord 频道中的社区消息同步至指定的 KOOK 频道。</p><p>使用本应用即表示您同意遵守本条款以及适用的法律法规、Discord 的相关政策和 KOOK 的相关规则。</p><h2 id="_1-服务说明" tabindex="-1">1. 服务说明 <a class="header-anchor" href="#_1-服务说明" aria-label="Permalink to “1. 服务说明”">​</a></h2><p>本应用主要提供以下功能：</p><ul><li>Discord 消息接收；</li><li>Discord 与 KOOK 之间的消息同步；</li><li>消息格式转换；</li><li>与消息同步相关的运行状态和错误处理。</li></ul><p>本应用不属于 Discord Inc. 或 KOOK 官方产品，也不代表 Discord 或 KOOK。</p><p>服务可能根据实际需要进行更新、修改、暂停或终止。</p><h2 id="_2-使用资格" tabindex="-1">2. 使用资格 <a class="header-anchor" href="#_2-使用资格" aria-label="Permalink to “2. 使用资格”">​</a></h2><p>您在使用本应用时必须：</p><ul><li>遵守适用的法律法规；</li><li>遵守 Discord 的服务条款及相关政策；</li><li>遵守 KOOK 的服务条款及相关政策；</li><li>遵守您所在 Discord 服务器的规则；</li><li>不利用本应用从事违法、欺诈、骚扰、滥用或其他违反平台规则的行为。</li></ul><h2 id="_3-discord-服务器管理员" tabindex="-1">3. Discord 服务器管理员 <a class="header-anchor" href="#_3-discord-服务器管理员" aria-label="Permalink to “3. Discord 服务器管理员”">​</a></h2><p>本应用是否能够访问 Discord 服务器及其频道取决于服务器管理员授予的权限。</p><p>服务器管理员负责决定：</p><ul><li>是否安装本应用；</li><li>将本应用添加到哪些服务器；</li><li>本应用可以访问哪些频道；</li><li>哪些消息可以被同步；</li><li>消息同步的目标 KOOK 频道。</li></ul><p>我们建议服务器管理员仅授予本应用完成实际功能所需要的最低权限。</p><h2 id="_4-消息同步" tabindex="-1">4. 消息同步 <a class="header-anchor" href="#_4-消息同步" aria-label="Permalink to “4. 消息同步”">​</a></h2><p>本应用的核心功能是将 Discord 消息同步至 KOOK。</p><p>由于 Discord 和 KOOK 属于不同的平台，消息在同步过程中可能发生以下变化：</p><ul><li>Markdown 或格式发生变化；</li><li>图片、附件或 Embeds 的显示方式发生变化；</li><li>用户名称或头像显示方式发生变化；</li><li>某些 Discord 特有的消息元素无法在 KOOK 中完全还原；</li><li>消息顺序可能因网络延迟等原因发生变化；</li><li>消息可能因为平台限制、网络错误或服务故障而无法同步。</li></ul><p>因此，我们不保证 Discord 消息能够在 KOOK 中完全一致地呈现。</p><h2 id="_5-用户内容" tabindex="-1">5. 用户内容 <a class="header-anchor" href="#_5-用户内容" aria-label="Permalink to “5. 用户内容”">​</a></h2><p>您在 Discord 或 KOOK 中发布的内容仍然由您自行负责。</p><p>本应用不会因为消息同步而取得您内容的所有权。</p><p>但是，为实现跨平台消息同步，本应用可能需要对消息进行临时处理、格式转换或传输。</p><p>您应确保自己拥有发布和传播相关内容所需的权利，并不得利用本应用传播违法或侵犯他人权利的内容。</p><h2 id="_6-禁止行为" tabindex="-1">6. 禁止行为 <a class="header-anchor" href="#_6-禁止行为" aria-label="Permalink to “6. 禁止行为”">​</a></h2><p>您不得利用本应用：</p><ul><li>从事违法活动；</li><li>侵犯他人的知识产权或其他合法权益；</li><li>进行骚扰、威胁或恶意攻击；</li><li>发送垃圾信息；</li><li>规避 Discord 或 KOOK 的安全机制；</li><li>滥用 Discord API 或 KOOK API；</li><li>尝试获取本应用无权访问的数据；</li><li>干扰本应用或其运行基础设施；</li><li>以其他方式违反 Discord、KOOK 或适用法律法规的要求。</li></ul><p>我们保留在必要情况下限制或终止相关服务使用的权利。</p><h2 id="_7-服务可用性" tabindex="-1">7. 服务可用性 <a class="header-anchor" href="#_7-服务可用性" aria-label="Permalink to “7. 服务可用性”">​</a></h2><p>我们会尽合理努力保持服务稳定运行，但不保证服务：</p><ul><li>永远可用；</li><li>不会出现中断；</li><li>不会出现延迟；</li><li>不会发生错误；</li><li>始终兼容 Discord 或 KOOK 的最新版本。</li></ul><p>如果 Discord、KOOK 或相关 API 发生变化，本应用可能需要进行技术调整，并可能暂时影响部分功能。</p><h2 id="_8-第三方服务" tabindex="-1">8. 第三方服务 <a class="header-anchor" href="#_8-第三方服务" aria-label="Permalink to “8. 第三方服务”">​</a></h2><p>本应用依赖 Discord、KOOK 以及其他可能的第三方基础设施。</p><p>第三方服务可能独立修改其：</p><ul><li>API；</li><li>服务条款；</li><li>隐私政策；</li><li>访问限制；</li><li>技术规范；</li><li>服务可用性。</li></ul><p>由于这些因素不完全由我们控制，因此我们无法保证本应用始终能够使用所有第三方功能。</p><h2 id="_9-知识产权" tabindex="-1">9. 知识产权 <a class="header-anchor" href="#_9-知识产权" aria-label="Permalink to “9. 知识产权”">​</a></h2><p>ETS2LA-CN 相关软件、网站、文档以及其他内容的知识产权归相应权利人所有。</p><p>本应用不得被理解为授予您任何未明确授予的知识产权许可。</p><p>对于第三方服务、软件、商标或内容，其知识产权仍归相应权利人所有。</p><h2 id="_10-免责声明" tabindex="-1">10. 免责声明 <a class="header-anchor" href="#_10-免责声明" aria-label="Permalink to “10. 免责声明”">​</a></h2><p>在适用法律允许的最大范围内，本应用按照“现状”和“可用状态”提供。</p><p>我们不保证本应用完全没有错误，也不保证消息同步一定及时、完整或准确。</p><p>由于以下原因造成的服务问题，我们不承担超出适用法律允许范围的责任：</p><ul><li>Discord 服务故障；</li><li>KOOK 服务故障；</li><li>网络故障；</li><li>API 变化；</li><li>第三方基础设施故障；</li><li>不可抗力；</li><li>用户或服务器管理员配置错误；</li><li>超出我们合理控制范围的其他情况。</li></ul><h2 id="_11-服务变更与终止" tabindex="-1">11. 服务变更与终止 <a class="header-anchor" href="#_11-服务变更与终止" aria-label="Permalink to “11. 服务变更与终止”">​</a></h2><p>我们可以根据实际需要：</p><ul><li>更新本应用；</li><li>修改服务功能；</li><li>暂停部分功能；</li><li>停止某些消息同步；</li><li>终止本应用服务。</li></ul><p>如果服务终止，我们会在合理范围内处理仍在运行中的相关服务。</p><h2 id="_12-隐私" tabindex="-1">12. 隐私 <a class="header-anchor" href="#_12-隐私" aria-label="Permalink to “12. 隐私”">​</a></h2><p>本应用对信息的收集、使用和处理方式由我们的《隐私政策》规定。</p><p>请在使用本应用前阅读：</p><p><strong>隐私政策：</strong></p><p><a href="https://docs.ets2la.cn/privacy" target="_blank" rel="noreferrer">https://docs.ets2la.cn/privacy</a></p><h2 id="_13-discord-和-kook-政策" tabindex="-1">13. Discord 和 KOOK 政策 <a class="header-anchor" href="#_13-discord-和-kook-政策" aria-label="Permalink to “13. Discord 和 KOOK 政策”">​</a></h2><p>使用本应用时，您仍然必须遵守 Discord 和 KOOK 各自的服务条款、开发者政策、社区规则以及其他适用政策。</p><p>本条款不会取代或修改 Discord 或 KOOK 与您之间的任何协议。</p><p>Discord 的服务条款和开发者相关政策由 Discord 官方发布。Discord 也明确要求第三方开发者遵守适用的开发者条款和政策。</p><h2 id="_14-条款变更" tabindex="-1">14. 条款变更 <a class="header-anchor" href="#_14-条款变更" aria-label="Permalink to “14. 条款变更”">​</a></h2><p>我们可能根据：</p><ul><li>服务功能变化；</li><li>技术架构变化；</li><li>Discord 或 KOOK 政策变化；</li><li>法律法规变化；</li><li>安全需求；</li></ul><p>更新本服务条款。</p><p>更新后的版本将在本页面发布，并更新“最后更新日期”。</p><p>继续使用本应用表示您接受更新后的条款。</p><h2 id="_15-联系我们" tabindex="-1">15. 联系我们 <a class="header-anchor" href="#_15-联系我们" aria-label="Permalink to “15. 联系我们”">​</a></h2><p>如果您对本服务条款或 ETS2LA-CN Discord App 有任何问题，可以通过 ETS2LA-CN 官方社区或项目页面提供的联系方式联系我们。</p><hr><p><strong>最后更新：2026 年 9 月 10 日</strong></p><hr><h1 id="terms-of-service" tabindex="-1">Terms of Service <a class="header-anchor" href="#terms-of-service" aria-label="Permalink to “Terms of Service”">​</a></h1><p><strong>Last updated: September 10, 2026</strong></p><p>Welcome to the Discord App and related message synchronization services provided by ETS2LA-CN.</p><p>These Terms of Service (the &quot;Terms&quot;) apply to your use of the ETS2LA-CN Discord App (the &quot;App&quot;) and its related message synchronization services.</p><p>The App is primarily used to synchronize community messages from designated Discord channels to designated KOOK channels.</p><p>By using the App, you agree to comply with these Terms, applicable laws and regulations, Discord policies, and KOOK rules.</p><h2 id="_1-service-description" tabindex="-1">1. Service Description <a class="header-anchor" href="#_1-service-description" aria-label="Permalink to “1. Service Description”">​</a></h2><p>The App primarily provides the following functions:</p><ul><li>Receiving Discord messages;</li><li>Synchronizing messages between Discord and KOOK;</li><li>Converting message formats;</li><li>Handling operational status and errors related to message synchronization.</li></ul><p>The App is not an official product of Discord Inc. or KOOK and does not represent Discord or KOOK.</p><p>The service may be updated, modified, suspended, or terminated as necessary.</p><h2 id="_2-eligibility" tabindex="-1">2. Eligibility <a class="header-anchor" href="#_2-eligibility" aria-label="Permalink to “2. Eligibility”">​</a></h2><p>When using the App, you must:</p><ul><li>Comply with applicable laws and regulations;</li><li>Comply with Discord&#39;s Terms of Service and related policies;</li><li>Comply with KOOK&#39;s Terms of Service and related policies;</li><li>Comply with the rules of the Discord server you are using;</li><li>Not use the App for illegal, fraudulent, harassing, abusive, or otherwise platform-violating activities.</li></ul><h2 id="_3-discord-server-administrators" tabindex="-1">3. Discord Server Administrators <a class="header-anchor" href="#_3-discord-server-administrators" aria-label="Permalink to “3. Discord Server Administrators”">​</a></h2><p>Whether the App can access a Discord server and its channels depends on the permissions granted by the server administrator.</p><p>Server administrators are responsible for deciding:</p><ul><li>Whether to install the App;</li><li>Which servers to add the App to;</li><li>Which channels the App may access;</li><li>Which messages may be synchronized;</li><li>The target KOOK channel for message synchronization.</li></ul><p>We recommend that server administrators grant the App only the minimum permissions required for its intended functions.</p><h2 id="_4-message-synchronization" tabindex="-1">4. Message Synchronization <a class="header-anchor" href="#_4-message-synchronization" aria-label="Permalink to “4. Message Synchronization”">​</a></h2><p>The core function of the App is to synchronize Discord messages to KOOK.</p><p>Because Discord and KOOK are different platforms, messages may change during synchronization, including:</p><ul><li>Markdown or formatting;</li><li>The display of images, attachments, or embeds;</li><li>The display of usernames or avatars;</li><li>Discord-specific message elements that cannot be fully reproduced in KOOK;</li><li>Message order due to network latency or other reasons;</li><li>Messages that cannot be synchronized because of platform restrictions, network errors, or service failures.</li></ul><p>Accordingly, we do not guarantee that Discord messages will be displayed identically in KOOK.</p><h2 id="_5-user-content" tabindex="-1">5. User Content <a class="header-anchor" href="#_5-user-content" aria-label="Permalink to “5. User Content”">​</a></h2><p>You remain responsible for the content you publish on Discord or KOOK.</p><p>The App does not obtain ownership of your content as a result of synchronizing messages.</p><p>However, to provide cross-platform message synchronization, the App may temporarily process, convert, or transmit messages.</p><p>You must ensure that you have the rights required to publish and distribute the relevant content, and must not use the App to distribute illegal content or content that infringes the rights of others.</p><h2 id="_6-prohibited-conduct" tabindex="-1">6. Prohibited Conduct <a class="header-anchor" href="#_6-prohibited-conduct" aria-label="Permalink to “6. Prohibited Conduct”">​</a></h2><p>You may not use the App to:</p><ul><li>Engage in illegal activities;</li><li>Infringe the intellectual property or other lawful rights of others;</li><li>Harass, threaten, or maliciously attack others;</li><li>Send spam;</li><li>Circumvent Discord or KOOK security mechanisms;</li><li>Abuse the Discord API or KOOK API;</li><li>Attempt to obtain data that the App is not authorized to access;</li><li>Interfere with the App or its operating infrastructure;</li><li>Otherwise violate Discord, KOOK, or applicable legal requirements.</li></ul><p>We reserve the right to restrict or terminate use of the relevant services when necessary.</p><h2 id="_7-service-availability" tabindex="-1">7. Service Availability <a class="header-anchor" href="#_7-service-availability" aria-label="Permalink to “7. Service Availability”">​</a></h2><p>We will make reasonable efforts to keep the service stable, but do not guarantee that the service will:</p><ul><li>Always be available;</li><li>Be uninterrupted;</li><li>Be free of delays;</li><li>Be error-free;</li><li>Always be compatible with the latest versions of Discord or KOOK.</li></ul><p>If Discord, KOOK, or a related API changes, the App may require technical adjustments, which may temporarily affect some functions.</p><h2 id="_8-third-party-services" tabindex="-1">8. Third-Party Services <a class="header-anchor" href="#_8-third-party-services" aria-label="Permalink to “8. Third-Party Services”">​</a></h2><p>The App depends on Discord, KOOK, and other third-party infrastructure that may be used.</p><p>Third-party services may independently modify their:</p><ul><li>APIs;</li><li>Terms of Service;</li><li>Privacy policies;</li><li>Access restrictions;</li><li>Technical specifications;</li><li>Service availability.</li></ul><p>Because these factors are not entirely under our control, we cannot guarantee that the App will always be able to use all third-party functions.</p><h2 id="_9-intellectual-property" tabindex="-1">9. Intellectual Property <a class="header-anchor" href="#_9-intellectual-property" aria-label="Permalink to “9. Intellectual Property”">​</a></h2><p>The intellectual property rights in ETS2LA-CN software, websites, documentation, and other content belong to their respective rights holders.</p><p>The App must not be understood as granting you any intellectual property license that is not expressly granted.</p><p>The intellectual property rights in third-party services, software, trademarks, or content remain with their respective rights holders.</p><h2 id="_10-disclaimer" tabindex="-1">10. Disclaimer <a class="header-anchor" href="#_10-disclaimer" aria-label="Permalink to “10. Disclaimer”">​</a></h2><p>To the maximum extent permitted by applicable law, the App is provided &quot;as is&quot; and &quot;as available.&quot;</p><p>We do not guarantee that the App will be completely error-free or that message synchronization will always be timely, complete, or accurate.</p><p>To the extent permitted by applicable law, we are not responsible for service problems caused by:</p><ul><li>Discord service failures;</li><li>KOOK service failures;</li><li>Network failures;</li><li>API changes;</li><li>Failures of third-party infrastructure;</li><li>Force majeure;</li><li>Incorrect configuration by users or server administrators;</li><li>Other circumstances beyond our reasonable control.</li></ul><h2 id="_11-service-changes-and-termination" tabindex="-1">11. Service Changes and Termination <a class="header-anchor" href="#_11-service-changes-and-termination" aria-label="Permalink to “11. Service Changes and Termination”">​</a></h2><p>We may, as necessary:</p><ul><li>Update the App;</li><li>Modify service functions;</li><li>Suspend some functions;</li><li>Stop certain message synchronization services;</li><li>Terminate the App service.</li></ul><p>If the service is terminated, we will handle related services that are still running to the extent reasonable.</p><h2 id="_12-privacy" tabindex="-1">12. Privacy <a class="header-anchor" href="#_12-privacy" aria-label="Permalink to “12. Privacy”">​</a></h2><p>The collection, use, and processing of information by the App are governed by our Privacy Policy.</p><p>Please read it before using the App:</p><p><strong>Privacy Policy:</strong></p><p><a href="https://docs.ets2la.cn/privacy" target="_blank" rel="noreferrer">https://docs.ets2la.cn/privacy</a></p><h2 id="_13-discord-and-kook-policies" tabindex="-1">13. Discord and KOOK Policies <a class="header-anchor" href="#_13-discord-and-kook-policies" aria-label="Permalink to “13. Discord and KOOK Policies”">​</a></h2><p>When using the App, you must continue to comply with Discord&#39;s and KOOK&#39;s respective Terms of Service, developer policies, community rules, and other applicable policies.</p><p>These Terms do not replace or modify any agreement between Discord or KOOK and you.</p><p>Discord&#39;s Terms of Service and developer-related policies are published by Discord. Discord also expressly requires third-party developers to comply with applicable developer terms and policies.</p><h2 id="_14-changes-to-these-terms" tabindex="-1">14. Changes to These Terms <a class="header-anchor" href="#_14-changes-to-these-terms" aria-label="Permalink to “14. Changes to These Terms”">​</a></h2><p>We may update these Terms of Service based on:</p><ul><li>Changes to service functions;</li><li>Changes to the technical architecture;</li><li>Changes to Discord or KOOK policies;</li><li>Changes to laws and regulations;</li><li>Security requirements.</li></ul><p>The updated version will be published on this page, together with an updated &quot;Last updated&quot; date.</p><p>Continued use of the App means that you accept the updated Terms.</p><h2 id="_15-contact-us" tabindex="-1">15. Contact Us <a class="header-anchor" href="#_15-contact-us" aria-label="Permalink to “15. Contact Us”">​</a></h2><p>If you have questions about these Terms of Service or the ETS2LA-CN Discord App, you may contact us through the official ETS2LA-CN community or the contact details provided on the project page.</p><hr><p><strong>Last updated: September 10, 2026</strong></p>',148)])])}const m=i(l,[["render",s]]);export{u as __pageData,m as default};
